solution.solution.cpp:
// 1, then 2, then 3 ... for the whole run of the program.
int nextEntityId()
{
    static int counter{ 0 };
    return ++counter;
}

unitTests:
TEST("counts up from one")
{
    CHECK_EQ(nextEntityId(), 1);
    CHECK_EQ(nextEntityId(), 2);
    CHECK_EQ(nextEntityId(), 3);
}
TEST("keeps counting across many calls")
{
    int last{ 0 };
    for (int i{ 0 }; i < 100; ++i) last = nextEntityId();
    CHECK_EQ(last, 103);
}

